"""Explicit MCQ adaptations of fully specified exercises the numeric grader cannot accept."""
from pathlib import Path
import json,uuid
OUT=Path(__file__).resolve().parents[1]/'content-releases/20261114_bank_review'
held=json.loads((OUT/'supported_before.json').read_text())+json.loads((OUT/'supported_extra_before.json').read_text())
definitions=[]
def add(prefix,topic,stem,choices,key,solution,also=()):
 sources=[next(q['id'] for q in held if q['id'].startswith(p)) for p in [prefix,*also]]
 definitions.append(dict(sources=sources,topic=topic,stem=stem,choices=choices,correct=key,explanation=solution))

add('074ada07','Logarithms and exponentials',r'For real x ≠ 0, y > 0, and z > 0, which expression equals $\ln\left(\frac{x^2\sqrt y}{z}\right)$?', [r'$2\ln|x|+\frac12\ln y-\ln z$',r'$2\ln|x|+2\ln y-\ln z$',r'$\ln|x|+\frac12\ln y-\ln z$',r'$2\ln|x|+\frac12\ln y+\ln z$'],'A',r'The quotient rule subtracts ln z. The power rules give ln(x²) = 2 ln|x| and ln(√y) = ½ ln y. The absolute value is necessary because x may be negative.')
add('09ecb437','Functions and transformations',r'What is the real domain of $h(x)=\frac{\sqrt{5-x}}{x+2}$?', ['x ≤ 5 and x ≠ −2','x < 5','x ≥ 5 and x ≠ −2','All real x except −2'],'A','The square root requires 5 − x ≥ 0, or x ≤ 5. The denominator must be nonzero, so x ≠ −2. The endpoint x = 5 is allowed.')
add('0eea2617','Rational expressions',r'What are the vertical and horizontal asymptotes of $y=\frac{2x+1}{x-3}$?', ['x = 3 and y = 2','x = −3 and y = 2','x = 3 and y = 1/2','x = −1/2 and y = 3'],'A','At x = 3 the denominator is zero and numerator is 7, so x = 3 is a vertical asymptote. Equal polynomial degrees give horizontal asymptote y = 2/1 = 2.')
add('1598aea2','Inequalities and absolute value',r'What is the complete real solution set of $2|x-4|=9$?', [r'$\{-\frac12,\frac{17}2\}$',r'$\{\frac12,\frac{17}2\}$',r'$\{-\frac12,\frac92\}$',r'$\{-5,13\}$'],'A','Divide by 2: |x − 4| = 9/2. Thus x = 4 ± 9/2, giving −1/2 and 17/2.',also=['6cb27c03'])
add('16b328b4','Complex numbers',r'For $i^2=-1$, what is $i^{37}$?', ['i','−i','1','−1'],'A','Powers of i repeat every four powers. Since 37 = 4(9) + 1, i³⁷ = (i⁴)⁹i = i.')
add('172ad291','Functions and transformations','The function y = 2x − 4 has domain {−4, 0, 6}. What is its range?', ['{−12, −4, 8}','{−8, 0, 12}','{−12, 0, 8}','{−4, 0, 6}'],'A','Evaluate each input: 2(−4) − 4 = −12; 2(0) − 4 = −4; 2(6) − 4 = 8.')
add('17976d6c','Circles','Which equation represents a circle with center (−2,5) and radius 4?', ['(x + 2)² + (y − 5)² = 16','(x − 2)² + (y + 5)² = 16','(x + 2)² + (y − 5)² = 4','(x − 2)² + (y − 5)² = 4'],'A','A circle with center (h,k) and radius r satisfies (x − h)² + (y − k)² = r². Substituting h = −2, k = 5, and r = 4 gives choice A.')
add('26abc145','Matrices',r'What is $\begin{pmatrix}2&1\\-3&4\end{pmatrix}+\begin{pmatrix}5&-2\\1&6\end{pmatrix}$?', [r'$\begin{pmatrix}7&-1\\-2&10\end{pmatrix}$',r'$\begin{pmatrix}7&3\\-4&10\end{pmatrix}$',r'$\begin{pmatrix}10&-2\\-3&24\end{pmatrix}$',r'$\begin{pmatrix}-3&3\\-4&-2\end{pmatrix}$'],'A','Add corresponding entries: 2 + 5 = 7, 1 − 2 = −1, −3 + 1 = −2, and 4 + 6 = 10.')
add('28077444','Systems of equations','Which ordered pair (x,y) solves 2x + y = 11 and x − y = 1?', ['(4,3)','(3,4)','(5,1)','(4,−3)'],'A','Adding the equations gives 3x = 12, so x = 4. Then y = x − 1 = 3. Both original equations are satisfied.')
add('296355c1','Rational expressions',r'The graph of $y=\frac{x^2-4}{x-2}$ has a removable discontinuity. At which point is the hole?', ['(2,4)','(−2,0)','(2,0)','(−2,4)'],'A','For x ≠ 2, factor and cancel to obtain y = x + 2. The excluded input x = 2 would give y = 4, so the hole is (2,4).')
add('29abef4e','Exponents and radicals',r'Which expression equals $\sqrt{72}$ in simplest radical form?', [r'$6\sqrt2$',r'$8\sqrt3$',r'$3\sqrt2$','36'],'A','Since 72 = 36 × 2, √72 = √36 × √2 = 6√2. The radicand 2 has no perfect-square factor greater than 1.')
add('2c17ac10','Matrices',r'What is the inverse of $\begin{pmatrix}3&1\\2&1\end{pmatrix}$?', [r'$\begin{pmatrix}1&-1\\-2&3\end{pmatrix}$',r'$\begin{pmatrix}1&1\\2&3\end{pmatrix}$',r'$\begin{pmatrix}3&-1\\-2&1\end{pmatrix}$',r'$\begin{pmatrix}-1&1\\2&-3\end{pmatrix}$'],'A','The determinant is 3(1) − 1(2) = 1. The inverse is 1/determinant times the matrix obtained by swapping diagonal entries and negating off-diagonal entries, giving A.')
add('317d7cf1','Quadratics and polynomials','What is the vertex of y = 2(x − 4)² − 7?', ['(4,−7)','(−4,−7)','(4,7)','(2,−7)'],'A','In y = a(x − h)² + k, the vertex is (h,k). Here h = 4 and k = −7.')
add('36341e49','Inequalities and absolute value','What is the complete solution set of |2x − 7| = 9?', ['{−1,8}','{1,8}','{−8,1}','{−1,1}'],'A','Set 2x − 7 = 9 or 2x − 7 = −9. These give x = 8 or x = −1.')
add('38daac79','Rational expressions','A car travels 180 km at v km/h, then travels the same distance back at (v + 20) km/h, where v > 0. Which expression gives its total travel time in hours?', [r'$\frac{180}{v}+\frac{180}{v+20}$',r'$\frac{360}{2v+20}$',r'$\frac{180}{v}+\frac{180}{20}$',r'$180v+180(v+20)$'],'A','For each leg, time = distance/speed. Add the outbound time 180/v and return time 180/(v + 20).')
add('3ba6f5a2','Systems of equations','Which ordered pair (x,y) solves 3x + 4 = −4y and x + 2y = 2?', ['(−8,5)','(8,−3)','(−4,3)','(2,0)'],'A','From x + 2y = 2, x = 2 − 2y. Substitute into 3x + 4 = −4y: 10 − 6y = −4y, so y = 5 and x = −8.')
add('3ec0a5f0','Systems of equations','The lines ax + 3y = 6 and 3x + 7y = −b intersect at (7,−4). What are a and b?', ['a = 18/7, b = 7','a = −18/7, b = 7','a = 18/7, b = −7','a = 6/7, b = 49'],'A','Substitute the intersection: 7a − 12 = 6 gives a = 18/7. Also 21 − 28 = −b gives b = 7.')
add('3f396c88','Volume and surface area','A cylinder has radius 4 units and height 9 units. What is its exact volume?', [r'$144\pi$',r'$36\pi$',r'$72\pi$',r'$324\pi$'],'A','Cylinder volume is πr²h = π(4²)(9) = 144π cubic units.')
add('451f180f','Quadratics and polynomials','Which is the complete factorization of 25x² − 121?', ['(5x − 11)(5x + 11)','(25x − 11)(x + 11)','(5x − 11)²','(5x + 11)²'],'A','This is the difference of squares (5x)² − 11², which factors as (5x − 11)(5x + 11).')
add('46097bfa','Coordinate geometry','What is the midpoint of the segment with endpoints (−3,7) and (5,−1)?', ['(1,3)','(4,−4)','(2,6)','(−1,−3)'],'A','Average the x-coordinates and y-coordinates separately: ((−3 + 5)/2, (7 − 1)/2) = (1,3).')
add('4820eb3d','Exponents and radicals',r'For x > 0, which expression equals $\sqrt[3]{x^5}$?', [r'$x^{5/3}$',r'$x^{3/5}$',r'$x^{15}$',r'$x^2$'],'A','A cube root is a power of 1/3. Thus (x⁵)^(1/3) = x^(5/3). The explicit positive domain avoids differing conventions for fractional powers.')
add('48c8b9b8','Linear functions and slope','Which equation has slope −2 and y-intercept 7?', ['y = −2x + 7','y = 2x + 7','y = −2x − 7','y = 7x − 2'],'A','In y = mx + b, the slope is m and y-intercept is b. Substitute m = −2 and b = 7.')
add('49104dc3','Rational expressions',r'What is the complete real solution set of $\frac1x+\frac1{x+2}=\frac34$?', [r'$\{-\frac43,2\}$',r'$\{-2,0\}$',r'$\{\frac43,2\}$',r'$\{-4,2\}$'],'A','The domain excludes x = 0 and x = −2. Multiplying by 4x(x + 2) gives 3x² − 2x − 8 = 0, or (3x + 4)(x − 2) = 0. Both −4/3 and 2 are allowed.')
add('59256413','Complex numbers','What are the solutions of x² + 4x + 13 = 0?', ['−2 ± 3i','2 ± 3i','−2 ± 3','−4 ± 13i'],'A','Completing the square gives (x + 2)² = −9. Therefore x + 2 = ±3i and x = −2 ± 3i.')
add('59721de1','Systems of equations','Which ordered pair (x,y) solves x + y = 9 and 2x − y = 6?', ['(5,4)','(4,5)','(3,6)','(6,3)'],'A','Adding gives 3x = 15, so x = 5. Then y = 9 − 5 = 4.')
add('5f033576','Complex numbers',r'Which expression equals $\frac{3+2i}{1-i}$?', [r'$\frac12+\frac52i$',r'$\frac52+\frac12i$',r'$\frac12-\frac52i$',r'$3+2i$'],'A','Multiply numerator and denominator by 1 + i. The denominator is 2; the numerator is 3 + 5i + 2i² = 1 + 5i. Divide by 2.')
add('5f17833f','Functions and transformations','Which sequence of transformations takes y = f(x) to y = −2f(x + 3) + 5?', ['Shift left 3; stretch vertically by 2 and reflect across the x-axis; shift up 5','Shift right 3; stretch vertically by 2 and reflect across the x-axis; shift up 5','Shift left 3; compress vertically by 1/2; shift up 5','Shift left 3; stretch vertically by 2 and reflect across the y-axis; shift down 5'],'A','The x + 3 shifts left 3. Multiplication by −2 stretches vertical distances by 2 and reflects across the x-axis. The final +5 shifts the result up 5.')
add('6037be14','Conic sections','Which conic is represented by 4x² − 9y² = 36?', ['Hyperbola','Ellipse','Parabola','Circle'],'A','Dividing by 36 gives x²/9 − y²/4 = 1. The squared terms have opposite signs, so the conic is a hyperbola.')
add('61a51dd3','Quadratics and polynomials','What is the complete solution set of 2x² − 7x + 3 = 0?', ['{1/2,3}','{−1/2,−3}','{1,3/2}','{−1/2,3}'],'A','Factor as (2x − 1)(x − 3) = 0. Thus x = 1/2 or x = 3.')
add('61c9e3fb','Circles','What are the center and radius of x² + y² − 6x + 8y − 11 = 0?', ['Center (3,−4), radius 6','Center (−3,4), radius 6','Center (3,−4), radius 36','Center (3,4), radius 6'],'A','Complete the squares: (x − 3)² + (y + 4)² = 11 + 9 + 16 = 36. The center is (3,−4) and radius √36 = 6.')
add('69b73d1b','Coordinate geometry','Point (2,3) is reflected across the y-axis, then across the x-axis. What is the resulting point?', ['(−2,−3)','(−2,3)','(2,−3)','(3,2)'],'A','The first reflection changes x to −2, producing (−2,3). The second changes y to −3, producing (−2,−3).')
add('6b29ba68','Functions and transformations','What is the inverse of f(x) = (x + 5)/3?', ['f⁻¹(x) = 3x − 5','f⁻¹(x) = 3x + 5','f⁻¹(x) = (x − 5)/3','f⁻¹(x) = (3 − x)/5'],'A','Let y = (x + 5)/3. Then 3y = x + 5, so x = 3y − 5. Interchange x and y to obtain the inverse.')
add('6c698a69','Triangles and similarity','A 30°–60°–90° triangle has short leg 7. What are its hypotenuse and long leg, respectively?', [r'$14,\ 7\sqrt3$',r'$7\sqrt3,\ 14$',r'$14,\ 7\sqrt2$',r'$7,\ 14$'],'A','The side ratio short : long : hypotenuse is 1 : √3 : 2. Multiplying by 7 gives hypotenuse 14 and long leg 7√3.')
add('737364bf','Ratios, percentages and unit conversion','Sarah invests $5,000 at a simple annual interest rate of 3%. Which expression gives the interest earned, in dollars, after t years?', ['150t','5000 + 150t','5000(1.03)ᵗ','150(1.03)ᵗ'],'A','Simple interest is principal × annual rate × time: 5000 × 0.03 × t = 150t. The question asks for interest, not the total account balance.')
add('7e911655','Area and perimeter','A rectangle has perimeter 80 units and width w units, where 0 < w < 40. Which expression gives its area?', ['w(40 − w)','w(80 − w)','40w','2w(40 − w)'],'A','From 2(length + width) = 80, length = 40 − w. Area is length × width = w(40 − w).')
add('7f518a2a','Trigonometry','For y = −3 cos(4x) + 2, with x measured in radians, what are the amplitude and period?', [r'$3,\ \pi/2$',r'$-3,\ \pi/2$',r'$3,\ 8\pi$',r'$2,\ \pi/2$'],'A','The amplitude is the absolute value of −3, which is 3. Period is 2π/|4| = π/2. The vertical shift does not change either quantity.')
add('84d52170','Exponents and radicals',r'For nonzero x and y, which expression equals $\frac{6x^3y^{-2}}{3x^{-1}y}$?', [r'$\frac{2x^4}{y^3}$',r'$\frac{2x^2}{y}$',r'$2x^4y^3$',r'$\frac{3x^4}{y^3}$'],'A','Divide coefficients to get 2. Subtract exponents when dividing: x^(3 − (−1)) = x⁴ and y^(−2 − 1) = y⁻³. Therefore the result is 2x⁴/y³.')
add('89153e97','Rational expressions',r'For x ≠ 3 and x ≠ −2, which expression equals $\frac{x^2-9}{x^2-x-6}$?', [r'$\frac{x+3}{x+2}$',r'$\frac{x-3}{x+2}$',r'$\frac{x+3}{x-2}$',r'$x+3$'],'A','Factor the numerator as (x − 3)(x + 3) and denominator as (x − 3)(x + 2). Cancel the common factor while retaining both original domain exclusions.')
add('8b343527','Quadratics and polynomials','Which is the complete factorization of x³ − 4x² − x + 4?', ['(x − 4)(x − 1)(x + 1)','(x + 4)(x − 1)(x + 1)','(x − 4)(x − 1)²','(x − 4)(x² + 1)'],'A','Group terms: x²(x − 4) − (x − 4) = (x − 4)(x² − 1). Factor the difference of squares.')
add('8b8cfb7a','Angles and polygons','A simple polygon has an interior-angle sum of 540°. How many sides does it have?', ['5','4','6','8'],'A','For n sides, the sum is (n − 2)180°. Solving (n − 2)180 = 540 gives n = 5.')
add('90f77567','Coordinate geometry','What is the reflection of (6,−2) across the line y = x?', ['(−2,6)','(2,−6)','(−6,2)','(6,2)'],'A','Reflection across y = x interchanges the coordinates: (x,y) becomes (y,x).')
add('967c3d8b','Conic sections',r'What are the vertices on the major axis of $\frac{x^2}{25}+\frac{y^2}{9}=1$?', ['(−5,0) and (5,0)','(0,−5) and (0,5)','(−3,0) and (3,0)','(−4,0) and (4,0)'],'A','The larger denominator is 25 beneath x², so the major axis is horizontal and semimajor length is √25 = 5. The center is (0,0), giving vertices (±5,0).')
add('9a06ec43','Inequalities and absolute value','What is the solution set of −3 ≤ 2x + 5 < 11?', ['−4 ≤ x < 3','−4 < x ≤ 3','−8 ≤ x < 6','−1 ≤ x < 8'],'A','Subtract 5 throughout: −8 ≤ 2x < 6. Divide throughout by positive 2, retaining the inequality directions and endpoint types.')
add('9dff9f8a','Trigonometry','In a right triangle, the side opposite acute angle θ is 9 and the hypotenuse is 15. What are sin θ and cos θ, respectively?', ['3/5 and 4/5','4/5 and 3/5','3/5 and 5/4','5/3 and 5/4'],'A','The adjacent side is √(15² − 9²) = 12. Thus sin θ = 9/15 = 3/5 and cos θ = 12/15 = 4/5.')
add('9fcd9239','Quadratics and polynomials','Which is the vertex form of y = x² − 6x + 5?', ['y = (x − 3)² − 4','y = (x + 3)² − 4','y = (x − 3)² + 5','y = (x − 6)² − 31'],'A','Complete the square: x² − 6x + 5 = (x² − 6x + 9) − 4 = (x − 3)² − 4.')
add('a77b0768','Quadratics and polynomials','Which is the complete factorization of x² − 7x + 12?', ['(x − 3)(x − 4)','(x + 3)(x + 4)','(x − 2)(x − 6)','(x + 3)(x − 4)'],'A','The numbers −3 and −4 multiply to 12 and add to −7, so the factorization is (x − 3)(x − 4).')
add('a9517d0e','Trigonometry','What are all solutions of sin x = 1/2 in the interval 0 ≤ x < 2π, with x in radians?', [r'$\pi/6,\ 5\pi/6$',r'$\pi/6,\ 7\pi/6$',r'$\pi/3,\ 2\pi/3$',r'$5\pi/6,\ 11\pi/6$'],'A','The reference angle is π/6. Sine is positive in Quadrants I and II, so the solutions are π/6 and π − π/6 = 5π/6.')
add('abe5dbb4','Logic','Which statement is the converse of “If Chris uses toothpaste X, then Chris does not get cavities”?',['If Chris does not get cavities, then Chris uses toothpaste X','If Chris does not use toothpaste X, then Chris gets cavities','If Chris gets cavities, then Chris does not use toothpaste X','If Chris uses toothpaste X, then Chris gets cavities'],'A','The converse of “if P, then Q” is “if Q, then P.” Interchange the hypothesis and conclusion without negating either. This asks about logical form, not the truth of the converse.')
add('abf3a097','Quadratics and polynomials','A 4 m by 6 m rectangular garden is surrounded on all sides by a sidewalk of uniform width w. The combined garden-and-sidewalk area is 40 m². What is the exact positive width w?', [r'$\frac{\sqrt{41}-5}{2}$',r'$\frac{\sqrt{41}+5}{2}$',r'$\sqrt{41}-5$',r'$\frac{\sqrt{41}-10}{2}$'],'A','The outer dimensions are 4 + 2w and 6 + 2w. Their product equals 40, so w² + 5w − 4 = 0. The quadratic formula gives (−5 ± √41)/2. Only (√41 − 5)/2 is positive.')
add('cb5328b0','Circles','Which equation describes a circle centered at (2,−3) with radius 5?', ['(x − 2)² + (y + 3)² = 25','(x + 2)² + (y − 3)² = 25','(x − 2)² + (y + 3)² = 5','(x − 2)² + (y − 3)² = 25'],'A','Use (x − h)² + (y − k)² = r² with h = 2, k = −3, and r = 5.')
add('d4fabad7','Linear functions and slope','Which equation represents the line through (2,5) with slope −3?', ['y = −3x + 11','y = −3x − 1','y = 3x − 1','y = −3x + 5'],'A','Point-slope form gives y − 5 = −3(x − 2). Expanding gives y = −3x + 11.')
add('dc91cd5c','Quadratics and polynomials','Which quadratic polynomial has roots 2 and −5 and leading coefficient 3?', ['3x² + 9x − 30','3x² − 9x − 30','x² + 3x − 10','3x² + 9x + 30'],'A','The polynomial is 3(x − 2)(x + 5) = 3(x² + 3x − 10) = 3x² + 9x − 30.')
add('dde56c95','Logarithms and exponentials','A population initially has 500 members and increases by 6% each year. Which function gives its population after t years?', ['P(t) = 500(1.06)ᵗ','P(t) = 500(0.06)ᵗ','P(t) = 500 + 6t','P(t) = 500(0.94)ᵗ'],'A','A 6% annual increase multiplies the previous population by 1.06 each year. Starting at 500 gives P(t) = 500(1.06)ᵗ.')
add('de4a2e58','Functions and transformations','What are the domain and range of y = |x| + 1?', ['Domain: all real numbers; range: y ≥ 1','Domain: x ≥ 0; range: y ≥ 1','Domain: all real numbers; range: y > 1','Domain: x ≥ 1; range: all real numbers'],'A','Absolute value is defined for every real x and is always nonnegative. Its minimum is 0 at x = 0, so y has minimum 1 and no upper bound.')
add('e6c907a4','Exponents and radicals',r'Which expression equals $\frac5{2+\sqrt3}$ and has a rational denominator?', [r'$10-5\sqrt3$',r'$10+5\sqrt3$',r'$5-2\sqrt3$',r'$\frac{10-5\sqrt3}{7}$'],'A','Multiply numerator and denominator by 2 − √3. The denominator becomes 4 − 3 = 1, leaving 5(2 − √3) = 10 − 5√3.')
add('e81728fa','Rational expressions',r'For x ≠ 3, which expression equals $\frac{x^2-9}{x-3}$?', ['x + 3','x − 3','x² + 3','x + 9'],'A','Factor x² − 9 = (x − 3)(x + 3). Since x ≠ 3, cancel x − 3 to obtain x + 3.')
add('ec0b80b3','Inequalities and absolute value','Which inequality has the same solution set as x + 8 ≥ 7 + 2x?', ['x ≤ 1','x ≥ 1','x ≤ −1','x ≥ −1'],'A','Subtract x + 7 from both sides to obtain 1 ≥ x, which is x ≤ 1. Equality at x = 1 is included.')
add('ed1dcc2d','Statistics and data analysis','What are the mean and median, respectively, of 3, 5, 5, 7, and 10?', ['6 and 5','5 and 6','6 and 6','5 and 5'],'A','The sum is 30, so the mean is 30/5 = 6. The third value in the sorted list is 5, so the median is 5.')
add('f8d3bf78','Matrices',r'What is $\begin{pmatrix}1&2\\0&3\end{pmatrix}\begin{pmatrix}4&1\\-2&5\end{pmatrix}$?', [r'$\begin{pmatrix}0&11\\-6&15\end{pmatrix}$',r'$\begin{pmatrix}4&2\\0&15\end{pmatrix}$',r'$\begin{pmatrix}0&9\\-6&15\end{pmatrix}$',r'$\begin{pmatrix}4&11\\-6&15\end{pmatrix}$'],'A','Multiply rows by columns: top-left 1(4) + 2(−2) = 0; top-right 1(1) + 2(5) = 11; bottom-left 0(4) + 3(−2) = −6; bottom-right 0(1) + 3(5) = 15.')

add('31ddb28a','Inequalities and absolute value','Which inequality describes exactly the solution set of −3x + 7 < 16?', ['x > −3','x < −3','x < −9','x > −9'],'A','Subtract 7: −3x < 9. Divide by −3 and reverse the inequality to get x > −3. Although x > −9 follows from the solution, it includes extra values and is not the exact solution set.',also=['ae11aecb'])
add('3eff8a14','Inequalities and absolute value','A craft shop spends less than $360 on bracelet and necklace kits. Each bracelet kit costs $6 and each necklace kit costs $12. It buys at least 8 more bracelet kits than necklace kits. Which purchase satisfies both conditions?', ['28 bracelet kits and 22 necklace kits','30 bracelet kits and 18 necklace kits','20 bracelet kits and 15 necklace kits','30 bracelet kits and 10 necklace kits'],'D','For D, cost = 6(30) + 12(10) = 300, which is less than 360; the difference is 20, which is at least 8. A and B exceed the budget. C meets the budget but its difference is only 5. The options are explicitly corrected instructor choices.')
add('6dc9e13a','Inequalities and absolute value',r'What is the complete real solution set of $\left|\frac{2-x}{7}\right|=\left|\frac{x+3}{5}\right|$?', [r'$\{-\frac{11}{12},-\frac{31}{2}\}$',r'$\{-\frac{11}{12}\}$',r'$\{\frac{11}{12},\frac{31}{2}\}$',r'$\{-\frac{11}{12},\frac{11}{6}\}$'],'A','Equal absolute values mean the quantities are equal or opposite. From 5(2 − x) = 7(x + 3), x = −11/12. From 5(2 − x) = −7(x + 3), x = −31/2. Both must be included.',also=['f452b8ea'])
add('7e080c5c','Functions and transformations','Which function has x-intercept (−1,0) and horizontal asymptote y = −3?', [r'$f(x)=\frac{-3(x+1)}{x+2}$',r'$f(x)=\frac{-3(x-1)}{x+2}$',r'$f(x)=\frac{3(x+1)}{x+2}$',r'$f(x)=\frac{-3(x+2)}{x+1}$'],'A','For A, x = −1 makes the numerator zero and leaves denominator 1, so the intercept is (−1,0). The ratio of leading coefficients is −3, giving horizontal asymptote y = −3. The other options fail at least one condition.')
add('7f8050b5','Statistics and data analysis','Dan’s first five scores are 70, 80, 80, 70, and 75. The scores 90 and 95 are added to form one cumulative seven-score data set. Relative to the original five scores, how do its mean and median change?', ['Both increase by 5','The mean increases by 5 and the median stays the same','The mean stays the same and the median increases by 5','Both increase by 10'],'A','The original sum is 375, mean 75, and median 75. The new sum is 560, mean 560/7 = 80, and median 80. Both increase by 5. The cumulative interpretation is explicitly stated.')
add('810b6716','Quadratics and polynomials','What is the complete real solution set of 2x² − 15 = −6?', [r'$\{-\frac{3\sqrt2}{2},\frac{3\sqrt2}{2}\}$',r'$\{-\sqrt3,\sqrt3\}$',r'$\{-\sqrt6,\sqrt6\}$','{−6,6}'],'A','Add 15 and divide by 2 to obtain x² = 9/2. Thus x = ±√(9/2) = ±3√2/2. These corrected choices include both roots.')
add('8bcc0c58','Exponents and radicals',r'For nonzero x and y, which expression equals $\frac{x^{16}y^9+x^6y^2}{x^2y^2}$?', [r'$x^{14}y^7+x^4$',r'$x^{14}y^7+x^4y$',r'$x^8y^7+x^3$',r'$x^{18}y^{11}+x^8y^4$'],'A','Divide each numerator term by x²y². Subtracting exponents gives x¹⁴y⁷ and x⁴, respectively. The second term has no remaining factor of y.')
add('a085f287','Exponents and radicals',r'For x ≠ 0 and y > 0, which expression equals $\frac{2x^2y}{x\sqrt y}$?', [r'$2x\sqrt y$',r'$2x^2\sqrt y$',r'$\frac{2x}{\sqrt y}$',r'$2xy$'],'A','Cancel one factor of x. Since y/√y = √y for y > 0, the expression becomes 2x√y. The choices are corrected so only one is equivalent on the stated domain.')
add('aacba8d8','Exponents and radicals',r'Which expression equals $\frac{\sqrt{15}}{\sqrt2}$?', [r'$\frac{\sqrt{30}}2$',r'$\frac{\sqrt{15}}2$',r'$\sqrt{30}$',r'$\frac{15}{2}$'],'A','Multiply numerator and denominator by √2 to get √30/2. The source’s second equivalent option has been replaced with an explicit instructor-authored distractor.')
add('af2c2124','Systems of equations','A cabinet contains 15 plates. Each has diameter 7 inches or 12 inches, and the sum of the 15 diameters is 140 inches. Let x count the 7-inch plates and y count the 12-inch plates. Which system models this situation?', ['x + y = 15; 7x + 12y = 140','x + y = 140; 7x + 12y = 15','x + y = 15; 12x + 7y = 140','7x + y = 15; x + 12y = 140'],'A','The plate count gives x + y = 15. Summing diameters gives 7x + 12y = 140. These equations have the valid integer solution x = 8, y = 7. This instructor adaptation explicitly corrects the impossible printed total of 14 inches to 140 inches.')
add('ec6acdfa','Systems of equations','For a nonzero real constant a, which ordered pair (x,y) solves x + ay = 2 and 3x − 2ay = 6?', ['(2,0)','(0,2/a)','(−2,0)','(2,2/a)'],'A','Multiply the first equation by 3 and subtract the second: 5ay = 0. Since a ≠ 0, y = 0, and then x = 2. The nonzero condition is explicitly added to exclude the infinitely-many-solutions case a = 0.')

